pub fn parse(input: *css.Parser) Result(FontStyle) {
            const property = (switch (FontStyleProperty.parse(input)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            return .{ .result = (switch (property) {
.normal => .normal,
.italic => .italic,
.oblique => |angle| {
{
                var second_angle = angle;
                _ = &second_angle;
                if (input.tryParse(css.css_values.angle.Angle.parse, .{}).asValue()) |a| {
                    _ = &a;
                    second_angle = a;
                }
                return .{ .result = .{ .oblique = .{ .a = angle, .b = second_angle } } };
            }
},
}) };
    }

pub fn toCss(self: *const FontStyle, dest: *Printer) PrintErr!void {
            switch (self.*) {
.normal => {
_ = try dest.writeStr("normal");
},
.italic => {
_ = try dest.writeStr("italic");
},
.oblique => |angle| {
_ = try dest.writeStr("oblique");
            if ((!angle.eql((&FontStyle.defaultObliqueAngle())))) {
                _ = try dest.writeChar(32);
                _ = try angle.toCss(dest);
