    }

pub fn defaultObliqueAngle() Size2D(Angle) {
            return .{ .a = FontStyleProperty.defaultObliqueAngle(), .b = FontStyleProperty.defaultObliqueAngle() };
    }
};

pub const FontFormat = union(enum) {
    woff: void,
    woff2: void,
    truetype: void,
    opentype: void,
    embedded_opentype: void,
    collection: void,
    svg: void,
    string: []const u8,

pub fn parse(input: *css.Parser) Result(FontFormat) {
            const s = (switch (input.expectIdentOrString()) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("woff", s)) {
                return .{ .result = .woff };
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("woff2", s)) {
                    return .{ .result = .woff2 };
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("truetype", s)) {
                        return .{ .result = .truetype };
                    } else {
                        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("opentype", s)) {
                            return .{ .result = .opentype };
                        } else {
                            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("embedded-opentype", s)) {
                                return .{ .result = .embedded_opentype };
                            } else {
                                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("collection", s)) {
                                    return .{ .result = .collection };
                                } else {
                                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("svg", s)) {
                                        return .{ .result = .svg };
                                    } else {
                                        return .{ .result = .{ .string = s } };
                                    }
                                }
                            }
                        }
                    }
                }
            }
    }

pub fn toCss(self: *const FontFormat, dest: *Printer) PrintErr!void {
            switch (self.*) {
.woff => {
_ = try dest.writeStr("woff");
},
.woff2 => {
_ = try dest.writeStr("woff2");
},
.truetype => {
_ = try dest.writeStr("truetype");
},
.opentype => {
_ = try dest.writeStr("opentype");
},
.embedded_opentype => {
_ = try dest.writeStr("embedded-opentype");
},
.collection => {
_ = try dest.writeStr("collection");
},
.svg => {
_ = try dest.writeStr("svg");
},
.string => {
_ = try dest.writeStr(self.string);
},
}
    }

pub fn deepClone(self: *const FontFormat, allocator: std.mem.Allocator) @This() {
            return css.implementDeepClone(@This(), self, allocator);
    }
};

