pub fn writeFontFaceProperty(d: *Printer, comptime prop: []const u8, value: anytype, comptime multi: bool) PrintErr!void {
        _ = try d.writeStr(prop);
        _ = try d.delim(58, false);
        if (comptime multi) {
            var idx: usize = 0;
            _ = &idx;
            const len = value.items.len;
            for (value.items) |val| {
                _ = &val;
                _ = try val.toCss(d);
                if ((idx < (len - 1))) {
                    _ = try d.delim(44, false);
                }
                idx = (idx + 1);
            }
        } else {
            _ = try value.toCss(d);
        }
}
